// Generated by sema from Action function definitions.
use crate::{ScopeId, SourceRange, SymbolId, ToyScopeContext};

pub fn contains_local(ctx: &ToyScopeContext, scope: ScopeId, name: &str) -> bool {
    ctx.scope_lookup_local(scope, name).is_some()
}

pub fn declare_variable(
    ctx: &mut ToyScopeContext,
    scope: ScopeId,
    name: &str,
    source: SourceRange,
) -> Result<SymbolId, &'static str> {
    if crate::sema_lib_gen::contains_local(&*ctx, scope, name) {
        ctx.note_error(source);
        return Err("identifier already declared");
    }
    let symbol = ctx.fresh_variable(scope, name, source);
    ctx.scope_bind(scope, name, symbol);
    Ok(symbol)
}

pub fn lookup_lexical(ctx: &ToyScopeContext, scope: ScopeId, name: &str) -> Option<SymbolId> {
    for current in ctx.scope_chain(scope) {
        let found = ctx.scope_lookup_local(current, name);
        if found.is_some() {
            return found;
        }
    }
    None
}

pub fn read_symbol(
    ctx: &mut ToyScopeContext,
    symbol: SymbolId,
    source: SourceRange,
) -> Result<SymbolId, &'static str> {
    if ctx.is_poisoned(symbol) {
        return Err("dependent error");
    }
    if !ctx.is_initialized(symbol) {
        ctx.note_error(source);
        return Err("variable read before initialization");
    }
    Ok(symbol)
}
